xml.Script:
        if not VarExists('W') then
            W := 0.5;
        include 'Figures\Scripts\Tetrahedron_Coordinates.inc';

        if not VarExists('Colors[0]') then begin
            clBlue   := '0000C8';
            clGreen  := '009600';
            clRed    := 'C80000';
            clYellow := 'FFFF00';

            Colors[0] := clBlue;
            Colors[1] := clGreen;
            Colors[2] := clRed;
            Colors[3] := clYellow;
        end;
